import json, random, string, subprocess, sys
sys.path.insert(0, '/workspace/tmp')
from ref import expected

random.seed(99)
ALPHA = string.printable + "\u00e9\u00ff\u0000\u0009\u001f\u007f\u0080"

def rv():
    return ''.join(random.choice(ALPHA) for _ in range(random.randint(0,5)))

NAMES = [':method',':scheme',':authority',':path',':status','host','content-length','te','cookie',
         'accept','x-list-a','x-list-','x-audit-z','connection','trailer','transfer-encoding','X-Bad',
         'range','vary','if-match','x-audit-','upgrade','keep-alive','http2-settings','proxy-connection',
         'accept-encoding','cache-control','if-none-match','pragma','','x-list-ab']
METHODS = ['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS','CONNECT','get','']
SCHEMES = ['http','https','HTTPS','ws','']
PATHS = ['/','/a%2Fb?x=1','*','//x','/a b','/a#b','http://x/','/a%2','/a%2f%41','/%zz','','/a\\b','/é','/a%41b']
AUTHS = ['demo.test','Demo.test:443','demo.test:0443','demo.test:8443','[2001:db8::1]','[2001:db8::1]:8080',
         '[::ffff:192.0.2.1]','192.0.2.1','01.2.3.4','1.2.3.4.5','demo.test.','-a.test','a-.test','_x.test',
         'demo.test:0','demo.test:65536','demo.test:65535','','a','[::1%25eth0]','[not-ip]','x'*300,
         'demo.test:80','demo.test:443','[::1]','[::1]:443','1.2.3.4:8080','abc.def.ghi.jkl.mno']
ROUTEKEYS = ['https://demo.test','http://demo.test','https://demo.test:8443','http://[2001:db8::1]:8080',
             'https://[::ffff:192.0.2.1]','http://192.0.2.1','https://demo.test:443','https://x.test']

def sect(trailer=False):
    pairs = []
    for _ in range(random.randint(0,5)):
        if random.random() < 0.7:
            name = random.choice([':method',':scheme',':authority',':path'])
            if name == ':method': val = random.choice(METHODS)
            elif name == ':scheme': val = random.choice(SCHEMES)
            elif name == ':path': val = random.choice(PATHS)
            else: val = random.choice(AUTHS)
        else:
            name = random.choice(['x-audit-a','x-audit-b','x-audit-','x-other','X-Audit-a',':method','x-list-a']+NAMES)
            val = rv()
        pairs.append([name, val])
    return pairs

def scenario():
    routes = {}
    for _ in range(random.randint(0,5)):
        routes[random.choice(ROUTEKEYS)] = random.choice(['a','b','c'])
    events = []
    for sid in random.sample(range(0,30), random.randint(0,6)):
        n = random.randint(1,6)
        seq = []
        for _ in range(n):
            t = random.choice(['headers','headers','data','unknown','fin','reset'])
            if t == 'headers': seq.append({'sid':sid,'type':'headers','fields':sect(random.random()<0.35)})
            elif t == 'data': seq.append({'sid':sid,'type':'data','hex':''.join(random.choice('0123456789abcdef') for _ in range(2*random.randint(0,4)))})
            elif t == 'unknown': seq.append({'sid':sid,'type':'unknown','frame_type':33,'hex':'aa'})
            else: seq.append({'sid':sid,'type':t})
        events.extend(seq)
    return {'routes':routes,'events':events}

diff = 0
for i in range(1500):
    scn = scenario()
    p = subprocess.run([sys.executable,'/workspace/submission/bridge.py'],
                       input=json.dumps(scn).encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode:
        print("CRASH", p.stderr.decode()[-500:]); diff += 1; continue
    got = json.loads(p.stdout)
    want = expected(scn)
    if got != want:
        diff += 1
        print("MISMATCH scenario:")
        print(json.dumps(scn))
        for k in ('streams','origins'):
            if got[k] != want[k]:
                print(" key", k)
                if k == 'streams':
                    for a,b in zip(got[k], want[k]):
                        if a != b: print("  got ", a, "\n  want", b)
                else:
                    for l in want[k]:
                        if got[k].get(l) != want[k][l]:
                            print("  ", l, "\n   got ", got[k].get(l), "\n   want", want[k][l])
        if diff > 4: break
print("done, diffs:", diff)
EOF
cd /workspace && python3 tmp/cmp.py 2>&1 | tail -40
